import{_ as o,r as s,o as p,c as i,e as a,a as c,s as l}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Settings & Config - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Database Settings","slug":"database-settings","link":"#database-settings","children":[{"level":3,"title":"Writing to a Settings Model","slug":"writing-to-a-settings-model","link":"#writing-to-a-settings-model","children":[]},{"level":3,"title":"Reading From a Settings Model","slug":"reading-from-a-settings-model","link":"#reading-from-a-settings-model","children":[]}]},{"level":2,"title":"Backend Settings Pages","slug":"backend-settings-pages","link":"#backend-settings-pages","children":[{"level":3,"title":"Settings Link Registration","slug":"settings-link-registration","link":"#settings-link-registration","children":[]},{"level":3,"title":"Setting the Page Navigation Context","slug":"setting-the-page-navigation-context","link":"#setting-the-page-navigation-context","children":[]}]},{"level":2,"title":"File-based Configuration","slug":"file-based-configuration","link":"#file-based-configuration","children":[{"level":3,"title":"Overriding Configuration Values","slug":"overriding-configuration-values","link":"#overriding-configuration-values","children":[]}]}],"relativePath":"2.x/plugin/settings.md","filePath":"2.x/plugin/settings.md"}'),r={name:"2.x/plugin/settings.md"};function g(u,n,d,k,h,m){const t=s("pre-heading"),e=s("post-heading");return p(),i("div",null,[a(t),n[0]||(n[0]=c("h1",null,"Settings & Config",-1)),a(e),n[1]||(n[1]=l(`<p>There are two ways to configure plugins - with back-end settings forms and with configuration files. Using database settings with back-end pages provide a better user experience, but they carry more overhead for the initial development. File-based configuration is suitable for configuration that is rarely modified.</p><p><a id="oc-database-settings"></a></p><h2 id="database-settings"><a href="#database-settings" class="header-anchor">#</a> Database Settings</h2><p>You can create models for storing settings in the database by implementing the <code>SettingsModel</code> behavior in a model class. This model can be used directly for creating the back-end settings form. You don&#39;t need to create a database table and a controller for creating the back-end settings forms based on the settings model.</p><p>The settings model classes should extend the Model class and implement the <code>\\System\\Behaviors\\SettingsModel</code> behavior. The settings models, like any other models, should be defined in the <strong>models</strong> subdirectory of the plugin directory. The model from the next example should be defined in the <code>plugins/acme/demo/models/UserSetting.php</code> file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Demo<span class="token punctuation">\\</span>Models</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Model</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">UserSetting</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * @var array implement these behaviors
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>SettingsModel</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token comment">/**
     * @var string settingsCode unique to this model
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$settingsCode</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;acme_demo_settings&#39;</span><span class="token punctuation">;</span>

    <span class="token comment">/**
     * @var string settingsFields configuration
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$settingsFields</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;fields.yaml&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <code>$settingsCode</code> property is required for settings models. It defines the unique settings key which is used for saving the settings to the database.</p><p>The <code>$settingsFields</code> property is required if you are going to build a back-end settings form based on the model. The property specifies a name of the YAML file containing the form fields definition. The form fields are described in the <a href="./../backend/forms.html">Backend forms</a> article. The YAML file should be placed to the directory with the name matching the model class name in lowercase. For the model from the previous example the directory structure would look like this:</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── demo
|           ├── models
|           |   ├── usersetting     <em>&lt;== Config Directory</em>
|           |   |   └── fields.yaml <em>&lt;== Form Fields</em>
|           |   └── <code>UserSetting.php</code> <em>&lt;== Model Class</em>
|           └── Plugin.php</p>
</code></pre><p>Settings models <a href="#oc-backend-settings-pages">can be registered</a> to appear on the <strong>Backend Settings area</strong>, but it is not a requirement - you can set and read settings values like any other model.</p><h3 id="writing-to-a-settings-model"><a href="#writing-to-a-settings-model" class="header-anchor">#</a> Writing to a Settings Model</h3><p>The settings model has the static <code>set</code> method that allows to save individual or multiple values. You can also use the standard model features for setting the model properties and saving the model.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">Acme<span class="token punctuation">\\</span>Demo<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>UserSetting</span><span class="token punctuation">;</span>

<span class="token comment">// Set a single value</span>
<span class="token class-name static-context">UserSetting</span><span class="token operator">::</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;api_key&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;ABCD&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Set an array of values</span>
<span class="token class-name static-context">UserSetting</span><span class="token operator">::</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;api_key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;ABCD&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Set object values</span>
<span class="token variable">$settings</span> <span class="token operator">=</span> <span class="token class-name static-context">UserSetting</span><span class="token operator">::</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$settings</span><span class="token operator">-&gt;</span><span class="token property">api_key</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;ABCD&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$settings</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="reading-from-a-settings-model"><a href="#reading-from-a-settings-model" class="header-anchor">#</a> Reading From a Settings Model</h3><p>The settings model has the static <code>get</code> method that enables you to load individual properties. Also, when you instantiate a model with the <code>instance</code> method, it loads the properties from the database and you can access them directly.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Outputs: ABCD</span>
<span class="token keyword">echo</span> <span class="token class-name static-context">UserSetting</span><span class="token operator">::</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token property">api_key</span><span class="token punctuation">;</span>

<span class="token comment">// Get a single value</span>
<span class="token keyword">echo</span> <span class="token class-name static-context">UserSetting</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;api_key&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Get a value and return a default value if it doesn&#39;t exist</span>
<span class="token keyword">echo</span> <span class="token class-name static-context">UserSetting</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_activated&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="oc-backend-settings-pages"></a></p><h2 id="backend-settings-pages"><a href="#backend-settings-pages" class="header-anchor">#</a> Backend Settings Pages</h2><p>The back-end contains a dedicated area for housing settings and configuration, it can be accessed by clicking the <strong>Settings</strong> link in the main menu. The Settings page contains a list of links to the configuration pages registered by the system and other plugins.</p><p><a id="oc-settings-link-registration"></a></p><h3 id="settings-link-registration"><a href="#settings-link-registration" class="header-anchor">#</a> Settings Link Registration</h3><p>The back-end settings navigation links can be extended by overriding the <code>registerSettings</code> method inside the <a href="./registration.html#oc-registration-file">Plugin registration class</a>. When you create a configuration link you have two options - create a link to a specific back-end page, or create a link to a settings model. The next example shows how to create a link to a back-end page.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerSettings</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;location&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Locations&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Manage available user countries and states.&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;category&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Users&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-globe&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/user/locations&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">500</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;keywords&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;geography place placement&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><blockquote><p><strong>Note</strong>: Backend settings pages should <a href="#oc-setting-the-page-navigation-context">set the settings context</a> in order to mark the corresponding settings menu item active in the System page sidebar. Settings context for settings models is detected automatically.</p></blockquote><p>The following example creates a link to a settings model. Settings models is a part of the settings API which is described above in the <a href="#oc-database-settings">Database settings</a> section.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerSettings</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;settings&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;User Settings&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Manage user based settings.&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;category&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Users&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-cog&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>User<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>UserSetting</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">500</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;keywords&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;security location&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;permissions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.users.access_settings&#39;</span><span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The optional <code>keywords</code> parameter is used by the settings search feature. If keywords are not provided, the search uses only the settings item label and description.</p><p><a id="oc-setting-the-page-navigation-context"></a></p><h3 id="setting-the-page-navigation-context"><a href="#setting-the-page-navigation-context" class="header-anchor">#</a> Setting the Page Navigation Context</h3><p>Just like <a href="./../backend/controllers-ajax.html#oc-setting-the-navigation-context">setting navigation context in the controller</a>, Back-end settings pages should set the settings navigation context. It&#39;s required in order to mark the current settings link in the System page sidebar as active. Use the <code>System\\Classes\\SettingsManager</code> class to set the settings context. Usually it could be done in the controller constructor:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword static-context">parent</span><span class="token operator">::</span><span class="token function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span>

    <span class="token class-name static-context">BackendMenu</span><span class="token operator">::</span><span class="token function">setContext</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;October.System&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;system&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;settings&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name static-context">SettingsManager</span><span class="token operator">::</span><span class="token function">setContext</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;You.Plugin&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;settings&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The first argument of the <code>setContext</code> method is the settings item owner in the following format: <strong>author.plugin</strong>. The second argument is the setting name, the same as you provided when <a href="#oc-settings-link-registration">registering the back-end settings page</a>.</p><p><a id="oc-file-based-configuration"></a></p><h2 id="file-based-configuration"><a href="#file-based-configuration" class="header-anchor">#</a> File-based Configuration</h2><p>Plugins can have a configuration file <strong>config.php</strong> in the <strong>config</strong> subdirectory of the plugin directory. The configuration files are PHP scripts that define and return an <strong>array</strong>. Example configuration file <strong>plugins/acme/demo/config/config.php</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span>

<span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">10</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;display&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">5</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</span></code></pre></div><p>Use the <code>Config</code> class for accessing the configuration values defined in the configuration file. The <code>Config::get($name, $default = null)</code> method accepts the plugin and the parameter name in the following format: <strong>Acme.Demo::maxItems</strong>. The second optional parameter defines the default value to return if the configuration parameter doesn&#39;t exist.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$maxItems</span> <span class="token operator">=</span> <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.demo::maxItems&#39;</span><span class="token punctuation">,</span> <span class="token number">50</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may also use a different filename for the configuration file and this affects the key name. For example, a configuration file named <strong>custom.php</strong> will prefix the key name with <code>custom</code>, using the following format: <strong>Acme.Demo::custom.maxItems</strong>. Example configuration file <strong>plugins/acme/demo/config/custom.php</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$maxItems</span> <span class="token operator">=</span> <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.demo::custom.maxItems&#39;</span><span class="token punctuation">,</span> <span class="token number">50</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="overriding-configuration-values"><a href="#overriding-configuration-values" class="header-anchor">#</a> Overriding Configuration Values</h3><p>A plugin configuration file can be overridden by the application by creating a local configuration file to match, for example, to override <strong>plugins/acme/demo/config/config.php</strong>, create a file called <strong>config/acme/todo/config.php</strong>. Inside the overridden configuration file you can return only values you want to override.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span>

<span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">20</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</span></code></pre></div><p>If you want to use separate configurations across different environments (eg: <strong>dev</strong>, <strong>production</strong>), consider using the <code>env()</code> helper to pull the value from an environment variable. The <code>env($name, $default = null)</code> function accepts the environment variable name and a default value if the variable doesn&#39;t exist.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span>

<span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">env</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;ACME_TODO_MAX_ITEMS&#39;</span><span class="token punctuation">,</span> <span class="token number">25</span><span class="token punctuation">)</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</span></code></pre></div><p>This will change the <code>maxItems</code> value when the environment variable <code>ACME_TODO_MAX_ITEMS</code> is set to any other value.</p>`,46))])}const b=o(r,[["render",g]]);export{v as __pageData,b as default};
